modules.script.grid:
-- Grid <-> world coordinate boundary.
-- Logic stays in grid space (row 0 = top, just under the HUD), matching the
-- Godot source. Only this module knows about the Defold Y-up flip.
local C = require "script.game_config"

local M = {}

-- z layers so gameplay objects draw above background tiles.
-- Default render clips z outside [-1, 1], so keep these small.
M.Z = { TILE = 0, OBSTACLE = 0.1, FOOD = 0.2, SEGMENT = 0.3, PLAYER = 0.4 }

function M.to_world(gx, gy, z)
  local x = gx * C.CELL_SIZE + C.CELL_SIZE * 0.5
  local y = (C.CELLS_Y - 1 - gy) * C.CELL_SIZE + C.CELL_SIZE * 0.5
  return vmath.vector3(x, y, z or 0)
end

function M.in_bounds(gx, gy)
  return gx >= 0 and gx < C.CELLS_X and gy >= 0 and gy < C.CELLS_Y
end

function M.key(gx, gy)
  return gx * 1000 + gy
end

function M.equal(a, b)
  return a.x == b.x and a.y == b.y
end

return M
